-- « Pilotage » (LecteurPilotage) : la table PILOTAGE_REQUETES de RIG v2 (colonnes et types de RIG_DEV, lu le 26/11/2026) et
-- des requetes de controle, chacune pour une regle de OPE_GENERER.cs. Les chiffres comptent des groupes d'impression d'un lot
-- « BANC9_PILOTAGE » absent de la table LOT : « Relancer un lot » ne les voit pas (son lecteur part des lots).
IF OBJECT_ID(N'v2.PILOTAGE_REQUETES') IS NULL
    CREATE TABLE v2.PILOTAGE_REQUETES (PILOT_ID_PILOT int NOT NULL PRIMARY KEY, PILOT_SQL varchar(max) NULL, PILOT_COLONNE int NULL,
        PILOT_LIGNE int NULL, PILOT_LIBELLE varchar(255) NULL, PILOT_TRAITEMENT varchar(50) NULL, PILOT_FEUILLE varchar(10) NULL);
IF OBJECT_ID(N'v2.GROUPE_IMPRESSION') IS NULL
    CREATE TABLE v2.GROUPE_IMPRESSION (GPIMP_NUM_GROUPE varchar(40) NOT NULL PRIMARY KEY, GPIMP_NOM_LOT varchar(255) NULL,
        GPIMP_DATE_DEBUT datetime NULL, GPIMP_DATE_FIN datetime NULL, GPIMP_NOM_IMPRIMANTE varchar(255) NULL, GPIMP_NB_TENTATIVES tinyint NULL,
        GPIMP_PHASE_TRAITEMENT varchar(10) NOT NULL);

-- La periode par defaut : le mois precedent (InitDate, OPE_GENERER.cs:123-143), fin a 23:59:59 (:253-254).
-- P01 le 10 du mois precedent et P02 son dernier jour a 23:00 : dans la periode (P02 : la fin portee a 23:59:59) ; jumeaux
-- refuses : P03 le 1er du mois courant a 0 h (apres la fin), P05 la veille du 1er du mois precedent (avant le debut). P04 : le 10
-- du meme mois un an plus tot, la colonne « un an plus tôt » (AddYears(-1), :170-171).
DECLARE @debut date = DATEADD(month, -1, DATEFROMPARTS(YEAR(@aujourdhui), MONTH(@aujourdhui), 1));
INSERT INTO v2.GROUPE_IMPRESSION (GPIMP_NUM_GROUPE, GPIMP_NOM_LOT, GPIMP_DATE_DEBUT, GPIMP_PHASE_TRAITEMENT) VALUES
    ('BANC9-P01', 'BANC9_PILOTAGE', DATEADD(hour, 10, CAST(DATEADD(day, 9, @debut) AS datetime)), 'E'),
    ('BANC9-P02', 'BANC9_PILOTAGE', DATEADD(hour, 23, CAST(DATEADD(day, -1, DATEADD(month, 1, @debut)) AS datetime)), 'E'),
    ('BANC9-P03', 'BANC9_PILOTAGE', CAST(DATEADD(month, 1, @debut) AS datetime), 'E'),
    ('BANC9-P04', 'BANC9_PILOTAGE', DATEADD(hour, 10, CAST(DATEADD(day, 9, DATEADD(year, -1, @debut)) AS datetime)), 'E'),
    ('BANC9-P05', 'BANC9_PILOTAGE', DATEADD(hour, 12, CAST(DATEADD(day, -1, @debut) AS datetime)), 'E');

-- Les cellules. 1900606 (feuille « 3 ») n'est pas generee (garde :273) ; jumeau : 1900601, feuille 1. 1900607 (requete vide)
-- est ignoree (:282) ; jumeau : 1900602. Les autres disent leur valeur, ou pourquoi la V3 ne la calcule pas.
INSERT INTO v2.PILOTAGE_REQUETES (PILOT_ID_PILOT, PILOT_FEUILLE, PILOT_LIGNE, PILOT_COLONNE, PILOT_LIBELLE, PILOT_TRAITEMENT, PILOT_SQL) VALUES
    (1900601, '1', 7, 2, 'Groupes du banc', NULL,
     'SELECT COUNT(*) AS NB FROM GROUPE_IMPRESSION WHERE GPIMP_NOM_LOT = ''BANC9_PILOTAGE'' AND GPIMP_DATE_DEBUT BETWEEN @DateMin AND @DateMax'),
    (1900602, '2', 7, 2, 'Groupes du banc sans année précédente', 'PASANNEEPREC',
     'SELECT COUNT(*) as ''nb'' FROM [dbo].[GROUPE_IMPRESSION] WHERE GPIMP_NOM_LOT = ''BANC9_PILOTAGE'' AND GPIMP_DATE_DEBUT BETWEEN @DateMin AND @DateMax'),
    (1900603, '1', 8, 2, 'Immatriculations du banc', NULL,
     'SELECT COUNT(DSSRC_NUM_GESTION) AS NB FROM DOSSIER_RCS INNER JOIN ACTION_RCS ON DSSRC_ID_DSRCS = ACTRC_ID_DSRCS WHERE ACTRC_DATE_ARRIVEE BETWEEN @DateMin AND @DateMax'),
    (1900604, '1', 9, 6, 'Encaissements du banc', 'ENCAISS', 'SELECT 1 AS NB'),
    (1900605, '2', 8, 2, 'Requête déclarée du banc', NULL, 'declare @x int = 1 select @x as NB from PILOTAGE_REQUETES'),
    (1900606, '3', 7, 2, 'Feuille inconnue du banc', NULL, 'SELECT 1 AS NB'),
    (1900607, '2', 9, 2, 'Sans requête du banc', NULL, '   '),
    (1900608, '2', 10, 2, 'Table absente du banc', NULL, 'SELECT COUNT(*) AS NB FROM TABLE_ABSENTE_BANC9'),
    (1900609, '1', 10, 2, 'Division du banc', NULL, 'SELECT 1 / 0 AS NB FROM PILOTAGE_REQUETES'),
    (1900610, '1', 11, 2, 'Valeur nulle du banc', NULL, 'SELECT CAST(NULL AS int) AS NB');

-- « Statistiques cour d'appel » (LecteurStatistiquesCourAppel) n'a pas de jeu a lui : ses quatre lignes comptent TOUTES les
-- instances du banc (le role J, F, R, IP), posees par les jeux des autres lots -- un .attendu changerait avec chacun d'eux. Ses
-- requetes sont controlees contre celles de RIG v2 sur RIG_DEV (compte rendu du lot 9). Il lui faut seulement les colonnes qu'il
-- lit, aux types de RIG_DEV (lu le 26/11/2026), pour que le banc le joue (section 4 : groupes et etats du descripteur).
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_DATE_ENROLEMENT datetime NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUM_ROLE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUM_ROLE varchar(11) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF OBJECT_ID(N'v2.DECISION_JUDICIAIRE') IS NULL
    CREATE TABLE v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC int NOT NULL PRIMARY KEY, DCJDC_ID_INSTN int NOT NULL);
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_DATE_PREVUE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_DATE_PREVUE datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_AVANT_DIRE_DROIT') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_AVANT_DIRE_DROIT varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DECISION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DECISION varchar(10) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_DELIBERER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_DELIBERER int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_PRONONCER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_PRONONCER int NULL;
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_SURSIS_STATUER bit NOT NULL DEFAULT 0,
        R_TYPEDECISI_ADD_EXPERTISE bit NOT NULL DEFAULT 0);
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_SURSIS_STATUER') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_SURSIS_STATUER bit NOT NULL CONSTRAINT DF_Banc9_Sursis DEFAULT 0 WITH VALUES;
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_ADD_EXPERTISE') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_ADD_EXPERTISE bit NOT NULL CONSTRAINT DF_Banc9_Expertise DEFAULT 0 WITH VALUES;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_ID_ADNC int NOT NULL);
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_CODE_PLUMITIF') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_CODE_PLUMITIF varchar(16) NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL);
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_EXTERIEUR') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_EXTERIEUR bit NOT NULL CONSTRAINT DF_Banc9_Exterieur DEFAULT 0 WITH VALUES;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_CODE_SOLUTION_2') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_CODE_SOLUTION_2 varchar(5) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_OUVERTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_OUVERTURE datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SOLUTION') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SOLUTION datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_SOLUTION_2') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_SOLUTION_2 datetime NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_DATE_CLOTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_DATE_CLOTURE datetime NULL;
